import React, { useState, useEffect } from 'react';
import { getExamData, deleteUserExamData, updateExamData } from '../services/api'; // Import the delete and update functions
import { fetchDurationOptions } from '../services/durationOptions'; // Import the fetchDurationOptions function

const ExamData = () => {
  const [examDataList, setExamDataList] = useState([]);
  const [filteredExamData, setFilteredExamData] = useState([]);
  const [errorMessage, setErrorMessage] = useState('');
  const [selectedFranchise, setSelectedFranchise] = useState('');
  const [editingExamId, setEditingExamId] = useState(null);
  const [editingData, setEditingData] = useState({
    name: '',
    examName: '',
    date: '',
    durationInMinutes: '',
    status: '',
  });
  const [durationOptions, setDurationOptions] = useState([]); // State for storing duration options

  // Fetch the exam data and duration options
  useEffect(() => {
    const fetchExamDataAndDurationOptions = async () => {
      try {
        // Fetch exam data
        const examDataResponse = await getExamData();
        if (examDataResponse && examDataResponse.length > 0) {
          const allExamData = examDataResponse.flatMap(franchise =>
            (franchise.examData || []).map(exam => ({
              franchiseId: franchise._id,
              franchiseName: franchise.name,
              location: franchise.location,
              name: exam.name,
              examName: exam.examName,
              date: exam.date ? new Date(exam.date).toISOString().split('T')[0] : '',
              duration: exam.durationInMinutes,
              status: exam.status,
              examId: exam._id,
            }))
          );
          setExamDataList(allExamData);
          setFilteredExamData(allExamData);
        } else {
          setErrorMessage('No exam data available for your franchises.');
        }

        // Fetch duration options
        const durations = await fetchDurationOptions();
        setDurationOptions(durations); // Set the duration options in the state
      } catch (error) {
        console.error('Error fetching exam data or duration options:', error);
        setErrorMessage('Unable to retrieve data. Please try again later.');
      }
    };

    fetchExamDataAndDurationOptions();
  }, []);

  // Handle franchise filter change
  const handleFranchiseChange = (e) => {
    const franchiseName = e.target.value;
    setSelectedFranchise(franchiseName);

    if (franchiseName === '') {
      setFilteredExamData(examDataList); // Show all data if no franchise is selected
    } else {
      const filteredData = examDataList.filter(exam => exam.franchiseName === franchiseName);
      setFilteredExamData(filteredData);
    }
  };

  // Handle edit functionality
  const handleEditClick = (exam) => {
    setEditingExamId(exam.examId); // Track the exam being edited
    setEditingData({
      franchiseId: exam.franchiseId, 
      name: exam.name,
      examName: exam.examName,
      date: exam.date,
      durationInMinutes: exam.duration, // Ensure this is correctly set
      status: exam.status,
    });
  };

  // Handle change in form inputs during editing
  const handleChange = (e) => {
    const { name, value } = e.target;
    setEditingData((prevData) => ({
      ...prevData,
      [name]: value,
    }));
  };

  // Save edited exam data
  const handleSave = async () => {
    try {
      const updatedExam = {
        ...editingData,
        date: new Date(editingData.date).toISOString().split('T')[0], // Format date
      };

      const payload = { examData: [updatedExam] };
      await updateExamData(editingData.franchiseId, editingExamId, payload);

      setExamDataList((prevState) =>
        prevState.map((examItem) =>
          examItem.examId === editingExamId ? { ...examItem, ...updatedExam } : examItem
        )
      );
      setFilteredExamData((prevState) =>
        prevState.map((examItem) =>
          examItem.examId === editingExamId ? { ...examItem, ...updatedExam } : examItem
        )
      );

      setEditingExamId(null); // Clear the editing state
    } catch (error) {
      console.error('Error updating exam data:', error);
      setErrorMessage('Unable to update exam data. Please try again later.');
    }
  };

  return (
    <div style={styles.container}>
      <h1 style={styles.header}>Exam Data</h1>

      {errorMessage ? (
        <p style={styles.error}>{errorMessage}</p>
      ) : (
        <>
          {/* Franchise filter dropdown */}
          <div style={styles.filterContainer}>
            <label style={styles.filterLabel}>Select Franchise:</label>
            <select
              value={selectedFranchise}
              onChange={handleFranchiseChange}
              style={styles.filterSelect}
            >
              <option value="">All Franchises</option>
              {filteredExamData.length > 0 &&
                [...new Set(filteredExamData.map(exam => exam.franchiseName))].map((franchise, index) => (
                  <option key={index} value={franchise}>
                    {franchise}
                  </option>
                ))}
            </select>
          </div>

          {filteredExamData.length > 0 ? (
            <div style={styles.tableContainer}>
              <table style={styles.table}>
                <thead>
                  <tr>
                    <th style={styles.th}>Franchise Name</th>
                    <th style={styles.th}>Location</th>
                    <th style={styles.th}>Exam Name</th>
                    <th style={styles.th}>Date</th>
                    <th style={styles.th}>Duration (minutes)</th>
                    <th style={styles.th}>Status</th>
                    <th style={styles.th}>Exam Taker Name</th>
                    <th style={styles.th}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredExamData.map((exam, index) => (
                    <tr key={index} style={styles.tr}>
                      <td style={styles.td}>{exam.franchiseName}</td>
                      <td style={styles.td}>{exam.location}</td>
                      <td style={styles.td}>
                        {editingExamId === exam.examId ? (
                          <select
                            name="examName"
                            value={editingData.examName}
                            onChange={handleChange}
                            style={styles.input}
                          >
                            <option value="Math Exam">Math Exam</option>
                            <option value="Science Exam">Science Exam</option>
                            <option value="History Exam">History Exam</option>
                          </select>
                        ) : (
                          exam.examName
                        )}
                      </td>
                      <td style={styles.td}>
                        {editingExamId === exam.examId ? (
                          <input
                            type="date"
                            name="date"
                            value={editingData.date}
                            onChange={handleChange}
                            style={styles.input}
                          />
                        ) : (
                          exam.date
                        )}
                      </td>
                      <td style={styles.td}>
                        {editingExamId === exam.examId ? (
                          <select
                            name="durationInMinutes"
                            value={editingData.durationInMinutes}
                            onChange={handleChange}
                            style={styles.input}
                          >
                            {durationOptions.map((duration, index) => (
                              <option key={index} value={duration}>
                                {duration} minutes
                              </option>
                            ))}
                          </select>
                        ) : (
                          exam.duration
                        )}
                      </td>
                      <td style={styles.td}>
                        {editingExamId === exam.examId ? (
                          <select
                            name="status"
                            value={editingData.status}
                            onChange={handleChange}
                            style={styles.input}
                          >
                            <option value="completed">Completed</option>
                            <option value="inprogress">In Progress</option>
                            <option value="absent">Absent</option>
                          </select>
                        ) : (
                          exam.status
                        )}
                      </td>
                      <td style={styles.td}>
                        {editingExamId === exam.examId ? (
                          <input
                            type="text"
                            name="name"
                            value={editingData.name}
                            onChange={handleChange}
                            style={styles.input}
                          />
                        ) : (
                          exam.name
                        )}
                      </td>
                      <td style={styles.td}>
                        {editingExamId === exam.examId ? (
                          <>
                            <button onClick={handleSave} style={styles.editButton}>
                              Save
                            </button>
                            <button onClick={handleCancel} style={styles.cancelButton}>
                              Cancel
                            </button>
                          </>
                        ) : (
                          <>
                            <button onClick={() => handleEditClick(exam)} style={styles.editButton}>
                              Edit
                            </button>
                            <button onClick={() => handleDelete(exam.examId, exam.franchiseId)} style={styles.deleteButton}>
                              Delete
                            </button>
                          </>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <p style={styles.noData}>No exam data available for the selected franchise.</p>
          )}
        </>
      )}
    </div>
  );
};

export default ExamData;
